import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import vm from 'node:vm';import crypto from 'node:crypto';import {JSDOM} from 'jsdom';import handler from '../api/purchasing.mjs';
const code=fs.readFileSync('integrations/purchasing/BudgetWeb.js','utf8')+'\n'+fs.readFileSync('integrations/purchasing/PurchaseWorkspace.js','utf8'),id='12345678-1234-4234-8234-123456789012';
function harness(){const ctx=staffContext({getCurrentSchoolYear:()=> '26_27',console:{error(){}},Utilities:{getUuid:()=>crypto.randomUUID(),computeDigest:(_,s)=>[...crypto.createHash('sha256').update(s).digest()],DigestAlgorithm:{SHA_256:'SHA_256'},formatDate:d=>d.toISOString().slice(0,10),parseDate:s=>new Date(s+'T12:00:00Z')},CONFIG:{MANAGER_SS_ID:'manager'}});vm.runInContext(code,ctx);const records={PurchaseBoardWeb:[],PurchaseRunsWeb:[],PurchaseAsbActionsWeb:[],PurchaseListsWeb:[],PurchaseListItemsWeb:[],PurchaseListEventsWeb:[]},writes=[];ctx.purchaseRecords_=name=>structuredClone(records[name]);ctx.purchaseSave_=(name,x)=>{writes.push(name);const clean=structuredClone(x),i=records[name].findIndex(r=>r.id===x.id);if(i<0)records[name].push(clean);else records[name][i]=clean;};return {ctx,records,writes};}
const admin={email:'mpenalver@bethelsd.org',name:'Administrator',admin:true,manager:true,periods:[]},student={email:'student@example.test',name:'Student',admin:false,manager:false,periods:['1']};
test('discussion creation derives author, enforces division membership and deduplicates requests',()=>{const {ctx,records}=harness(),request={id,title:'Motors',reason:'Build a robot',quantity:2,divisions:['2'],fund:'CTE'};assert.equal(ctx.purchaseCreate_(student,request).status,400);request.divisions=['1'];assert.equal(ctx.purchaseCreate_(student,request).status,200);assert.equal(ctx.purchaseCreate_(student,request).status,200);assert.equal(records.PurchaseBoardWeb.length,1);assert.equal(records.PurchaseBoardWeb[0].author,'Student');assert.equal(ctx.purchaseVisible_({...student,email:'other@example.test',periods:['2']},records.PurchaseBoardWeb[0]),false);});
test('students cannot manage requisitions; directors cannot approve purchases; stale revisions are rejected',()=>{const {ctx,records}=harness();ctx.purchaseCreate_(student,{id,title:'Motors',reason:'Build a robot',quantity:2,divisions:['1'],fund:'CTE'});const r={operation:'update',id,revision:1,stage:'approved',unitCost:10,shipping:0,quantity:2,fund:'CTE'};assert.equal(ctx.purchaseChange_(student,r).status,403);assert.equal(ctx.purchaseChange_({...student,manager:true},r).status,403);r.stage='requisition';assert.equal(ctx.purchaseChange_({...student,manager:true},r).status,200);assert.equal(records.PurchaseBoardWeb[0].unitCost,10);assert.equal(ctx.purchaseChange_(admin,r).status,409);assert.equal(ctx.purchaseChange_(admin,{...r,revision:2,stage:'ordered'}).status,400);});
test('public discussion records omit emails and receipt locations',()=>{const {ctx,records}=harness();ctx.purchaseCreate_(student,{id,title:'Motors',reason:'Build',quantity:1,divisions:['1'],fund:'ASB'});const record=records.PurchaseBoardWeb[0];record.comments.push({id,author:'Student',email:'private@example.test',text:'Useful',at:'today'});const s=JSON.stringify(ctx.purchasePublic_(record));assert.equal(s.includes('@'),false);assert.equal(s.includes('receipt'),false);});
test('purchase values preserve legacy column positions and real food cost',()=>{const {ctx}=harness(),v=ctx.purchaseValues_({type:'New Purchase',vendor:'Test',vendorDetails:'',items:[],day:'2026-10-30',description:'Food',original:'',foodType:'Yes: CTE',taxed:'Yes',attendees:['A','B'],amount:55.42,shipping:0},'receipt');assert.equal(v.length,45);assert.equal(v[35],'10/30/2026');assert.equal(v[39],'A; B');assert.equal(v[40],'receipt');assert.equal(v[41],55.42);});
test('food submissions require the dated attendee review; amounts must have cents precision',()=>{const {ctx}=harness(),d={type:'New Purchase',vendor:'Vendor',day:'2026-10-30',description:'Food',amount:25,shipping:0,taxed:'Yes',foodType:'Yes: CTE',links:[],attendees:[],attendanceConfirmed:false,attendanceGroup:'Attendance'},options={types:['New Purchase'],foodTypes:['Yes: CTE']};assert.throws(()=>ctx.purchaseDraft_({draft:d},options),/students/);d.attendees=['Student'];d.attendanceConfirmed=true;assert.equal(ctx.purchaseDraft_({draft:d},options).amount,25);d.amount=25.555;assert.throws(()=>ctx.purchaseDraft_({draft:d},options),/fields/);});
function commitHarness(fail=false){const {ctx,records,writes}=harness();let calls=0,rows=0;records.PurchaseRunsWeb.push({id,email:admin.email,state:'preview',expires:Date.now()+60000,budgetRevision:'budget',draft:{type:'New Purchase',vendor:'Vendor',day:'2026-10-30',description:'Tools',amount:10,shipping:0,taxed:'Yes',foodType:'No',links:[],items:[],attendees:[]}});ctx.purchaseBudget_=()=>({revision:'budget'});ctx.purchaseOptions_=()=>({});ctx.purchaseDraft_=()=>true;ctx.purchaseLinked_=()=>[];ctx.purchaseValues_=()=>Array(45).fill('');const headers=Array(45).fill('');headers[0]='Timestamp';headers[2]='Vendor';headers[35]='Purchase Date';headers[40]='Receipt';headers[41]='Amount';const sheet={getRange:()=>({getDisplayValues:()=>[headers],setValues(){rows++;}}),getLastRow:()=>10,getParent:()=>({})};ctx.SpreadsheetApp={openById:()=>({getSheetByName:()=>sheet}),flush(){}};ctx.processFormResponse=()=>{calls++;if(fail)throw Error('uncertain email');};ctx.syncCurrentBudgetToNest_=()=>{throw Error('maintenance unavailable');};return {ctx,records,writes,calls:()=>calls,rows:()=>rows};}
test('commit is durable and idempotent; maintenance failure does not permit a second transaction',()=>{const {ctx,calls,rows,records}=commitHarness();assert.equal(ctx.purchaseCommit_(admin,{id}).saved,true);assert.equal(ctx.purchaseCommit_(admin,{id}).saved,true);assert.equal(calls(),1);assert.equal(rows(),1);assert.equal(records.PurchaseRunsWeb[0].state,'complete');assert.match(records.PurchaseRunsWeb[0].message,/refresh is pending/);});
test('uncertain processing is held for review without automatic retries or duplicate emails',()=>{const {ctx,calls,rows,records}=commitHarness(true);assert.equal(ctx.purchaseCommit_(admin,{id}).state,'review-required');assert.equal(ctx.purchaseCommit_(admin,{id}).state,'review-required');assert.equal(calls(),1);assert.equal(rows(),1);assert.equal(records.PurchaseRunsWeb[0].sourceRow,11);});
test('school bridge rechecks roles and blocks browser-supplied identity',()=>{const source=fs.readFileSync('google-spinner/Purchasing.js','utf8'),ctx=staffContext({OWNER_EMAILS:[admin.email],email_:x=>x,LEADERSHIP_DATABASE:'leadership',Sheets:{Spreadsheets:{Values:{get:()=>({values:[]})}}},hash_:x=>x,PERIODS:{1:'book'},memberEmail_:x=>x,rows_:()=>[['Student','student@example.test']],inventoryAllowed_:()=>false,authSession_:()=>({email:student.email,username:'student'}),PropertiesService:{getScriptProperties:()=>({})},UrlFetchApp:{fetch:()=>{throw Error('must not forward')}}});vm.runInContext(source,ctx);assert.equal(ctx.purchasingDispatch_({session:'test',operation:'commit',actor:admin}).status,403);assert.equal(ctx.purchasingDispatch_({session:'test',operation:'update'}).status,403);assert.equal(ctx.purchasingActor_({email:student.email,username:'student'}).admin,false);});
function response(){return {setHeader(){},status(n){this.code=n;return this;},json(data){this.data=data;return this;}};}
test('API rejects anonymous reads, cross-origin writes, and identity injection',async()=>{let res=response();await handler({method:'GET',headers:{}},res);assert.equal(res.code,401);const headers={cookie:'__Host-nest-auth='+'a'.repeat(64),'content-type':'application/json',origin:'https://evil.test'};res=response();await handler({method:'POST',headers,body:{operation:'commit',id}},res);assert.equal(res.code,403);res=response();await handler({method:'POST',headers:{...headers,origin:'https://gknest.org'},body:{operation:'view',actor:admin}},res);assert.equal(res.code,400);});
test('logout clears discussion, receipt input, preview, history and equipment frame',async()=>{const dom=new JSDOM(fs.readFileSync('purchasing.html','utf8'),{url:'https://gknest.org/purchasing',runScripts:'outside-only'}),w=dom.window;w.NestAuth={identity:{signedIn:true},ready:Promise.resolve()};w.fetch=async()=>({ok:true,json:async()=>({access:{admin:false,manager:false,periods:['1']},requests:[{id,revision:1,title:'Private division request',reason:'Test',divisions:['1'],fund:'CTE',stage:'discussion',quantity:1,unitCost:null,shipping:0,comments:[],history:[]}],budget:null})});w.eval(fs.readFileSync('js/purchasing.js','utf8'));await new Promise(r=>setTimeout(r,20));assert.match(w.document.querySelector('#purchase-board').textContent,/Private division/);w.NestAuth.identity.signedIn=false;w.document.dispatchEvent(new w.Event('nest-auth-change'));assert.equal(w.document.querySelector('#purchase-workspace').hidden,true);assert.equal(w.document.querySelector('#purchase-board').textContent,'');assert.equal(w.document.querySelector('#purchase-equipment iframe'),null);dom.window.close();});
async function adminBrowser(records=[],vendorChoices=['Vendor'],historyRecords=[]){const dom=new JSDOM(fs.readFileSync('purchasing.html','utf8'),{url:'https://gknest.org/purchasing',runScripts:'outside-only'}),w=dom.window,calls=[];w.NestAuth={identity:{signedIn:true},ready:Promise.resolve()};w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;};w.fetch=async(url,opts)=>{const body=opts.body?JSON.parse(opts.body):{operation:'view'};calls.push(body);const data=body.operation==='view'?{access:{admin:true,manager:true,periods:['1','CTSO']},requests:records,budget:{balance:2484.55},runs:historyRecords}:body.operation==='admin'?{options:{vendors:vendorChoices,foodTypes:['No.','Yes: ASB','Yes: CTE'],previous:['10/29/2026_Vendor_$10.00']}}:body.operation==='attendance'?{names:['Fictional Student'],source:'NEST™ Sign-In System',day:body.day}:{};return {ok:true,status:200,json:async()=>data};};w.eval(fs.readFileSync('js/purchasing.js','utf8'));await new Promise(r=>setTimeout(r,20));return {w,dom,calls};}
test('food selection automatically loads dated attendance and requires review',async()=>{const {w,dom,calls}=await adminBrowser();try{w.document.querySelector('[data-panel="checkout"]').click();const type=w.document.querySelector('#purchase-food-type');type.value='Yes: CTE';type.dispatchEvent(new w.Event('change',{bubbles:true}));await new Promise(r=>setTimeout(r,20));assert.equal(calls.filter(c=>c.operation==='attendance').length,1);assert.match(calls.find(c=>c.operation==='attendance').day,/^\d{4}-\d{2}-\d{2}$/);assert.equal(w.document.querySelector('[name="attendees"]').value,'Fictional Student');assert.equal(w.document.querySelector('[name="attendanceConfirmed"]'),null);assert.equal(w.document.querySelector('#purchase-food').hidden,false);}finally{dom.window.close();}});
