test('attendance selects only the requested Pacific date and Attendance location, supports guests and deduplicates names',()=>{const {ctx}=harness();const response=(day,location,name,first,last)=>({getTimestamp:()=>new Date(day+'T12:00:00Z'),getItemResponses:()=>[['Choose your location',location],['Select your name  ',name],['FIRST name',first],['LAST name',last]].map(([title,v])=>({getItem:()=>({getTitle:()=>title}),getResponse:()=>v||''}))});ctx.FormApp={openById:()=>({getResponses:()=>[response('2026-10-30','Attendance','Student A'),response('2026-10-30','Attendance','Student A'),response('2026-10-30','Library','Student B'),response('2026-10-29','Attendance','Student C'),response('2026-10-30','Attendance','','Guest','Example')]})};const result=ctx.purchaseAttendance_('2026-10-30','Attendance');assert.deepEqual(Array.from(result.names),['Example, Guest','Student A']);assert.equal(result.count,3);});
