test('ASB previews require admin, current record revision, verified signatures, and the live executive queue',()=>{const {ctx,records}=harness();ctx.purchaseAsbRows_=()=>[{id:'asb',revision:'v1',action:'Select Action...',status:'Created',vendor:'Vendor',total:'25.00',choices:['Approved','Send to ASB Director']}];ctx.getOrderedExecQueue_=()=>[{email:'executive@example.test'}];ctx.getRecipientEmail_=()=> 'clerk@example.test';let r={id:'asb',revision:'v1',change:'Approved',ticket:id};assert.equal(ctx.purchaseAsbPreview_(student,r).status,403);assert.equal(ctx.purchaseAsbPreview_(admin,{...r,revision:'old'}).status,409);assert.equal(ctx.purchaseAsbPreview_(admin,r).preview.recipients[0],'executive@example.test');assert.equal(ctx.purchaseAsbPreview_(admin,{...r,change:'Send to ASB Director'}).status,200);assert.equal(ctx.purchaseAsbPreview_(admin,{...r,change:'Send to ASB Director',signaturesConfirmed:true}).preview.recipients[0],'clerk@example.test');records.PurchaseAsbActionsWeb[0].state='review-required';assert.equal(ctx.purchaseAsbPreview_(admin,r).status,409);});
test('ASB commits call the existing request handler once and retain uncertain sends for review',()=>{for(const failure of [false,true]){const {ctx,records}=harness();records.PurchaseAsbActionsWeb.push({id,email:admin.email,state:'preview',request:'asb',revision:'v1',expires:Date.now()+60000,change:'Approved'});ctx.purchaseAsbRows_=()=>[{id:'asb',revision:'v1',row:4}];const writes=[];ctx.SpreadsheetApp={openById:()=>({getSheetByName:()=>({getRange:()=>({setValue:x=>writes.push(x)})})}),flush(){}};let sends=0;ctx.onEdit_Requests=()=>{sends++;if(failure)throw Error('delivery uncertain');};assert.equal(ctx.purchaseAsbCommit_(admin,{ticket:id}).saved,!failure);ctx.purchaseAsbCommit_(admin,{ticket:id});assert.equal(sends,1);assert.equal(writes.length,1);assert.equal(records.PurchaseAsbActionsWeb[0].state,failure?'review-required':'complete');}});
