test('discussion team uses current rostered leadership, includes all Robotics executives, and omits email addresses',()=>{let leaders=[['1','','Division Manager','Manager Example','manager@test'],['2','','Assistant Manager','Assistant Example','assistant@test'],['CTSO','','Chief Financial Officer','CFO Example','cfo@test'],['CTSO','','Chief Operations Officers','COO Example','coo@test'],['CTSO','','Executive Vice-President','EVP Example','evp@test'],['2','','Director of Inventory','Inventory Example','inventory@test'],['2','','Division Manager','Stale Example','stale@test'],['1','','Director of Safety','Safety Example','safety@test'],['1','','Assistant Manager','Manager Example','manager@test']];const source=fs.readFileSync('google-spinner/Purchasing.js','utf8'),rosters={'1':['manager@test','safety@test'],'2':['assistant@test','inventory@test'],CTSO:['cfo@test','coo@test','evp@test']},ctx=staffContext({OWNER_EMAILS:[admin.email],email_:x=>String(x||'').toLowerCase(),PERIODS:{1:'a',2:'b',CTSO:'c'},rows_:p=>(rosters[p]||[]).map(email=>['Example',email]),memberEmail_:x=>x,LEADERSHIP_DATABASE:'leaders',Sheets:{Spreadsheets:{Values:{get:()=>({values:leaders})}}},hash_:x=>crypto.createHash('sha256').update(x).digest('hex')});vm.runInContext(source,ctx);const manager=ctx.purchasingActor_({email:'manager@test',username:'manager'});assert.equal(manager.allDivisionLeadership,true);assert.equal(manager.manager,false);assert.equal(manager.discussionTeam.length,6);assert.equal(manager.discussionTeam.find(x=>x.name==='Manager Example').roles.length,2);assert.equal(JSON.stringify(manager.discussionTeam).includes('@'),false);assert.equal(ctx.purchasingActor_({email:'cfo@test',username:'cfo'}).allDivisionLeadership,true);assert.equal(ctx.purchasingActor_({email:'inventory@test',username:'inventory'}).manager,true);assert.equal(ctx.purchasingActor_({email:'safety@test',username:'safety'}).allDivisionLeadership,false);leaders=[];assert.equal(ctx.purchasingActor_({email:'manager@test',username:'manager'}).allDivisionLeadership,false);});
