function sampleRequisition(extra={}){return {id,revision:1,title:'Motors',reason:'Build robot',divisions:['1'],allDivisions:false,fund:'CTE',stage:'requisition',quantity:2,unitCost:12.5,shipping:5,author:'Example',comments:[],history:[],...extra};}
test('prepare purchase is disabled with no selection and fills and reveals checkout after a selection',async()=>{const {w,dom}=await adminBrowser([sampleRequisition()]);try{const button=w.document.querySelector('#purchase-prepare');assert.equal(button.disabled,true);const checkbox=w.document.querySelector('#purchase-requisition-list input[type="checkbox"]');checkbox.click();assert.equal(button.disabled,false);assert.match(button.textContent,/\(1\)/);assert.match(w.document.querySelector('#purchase-prepare-message').textContent,/30.00/);button.click();assert.equal(w.document.querySelector('#purchase-checkout').hidden,false);assert.equal(w.document.querySelector('#purchase-requisitions').hidden,true);assert.equal(w.document.querySelector('#purchase-admin-form [name="amount"]').value,'30.00');assert.match(w.document.querySelector('#purchase-checkout-summary').textContent,/Motors/);assert.match(w.document.querySelector('#purchase-admin-form [name="description"]').value,/2 × Motors/);}finally{dom.window.close();}});
test('mixed CTE and ASB selections give an inline explanation instead of preparing an invalid purchase',async()=>{const {w,dom}=await adminBrowser([sampleRequisition(),sampleRequisition({id:'22345678-1234-4234-8234-123456789012',fund:'ASB',title:'ASB equipment'})]);try{w.document.querySelectorAll('#purchase-requisition-list input[type="checkbox"]').forEach(x=>x.click());assert.equal(w.document.querySelector('#purchase-prepare').disabled,true);assert.match(w.document.querySelector('#purchase-prepare-message').textContent,/one funding source/);}finally{dom.window.close();}});
test('item links preserve product destinations and never offer the NEST menu as a product',async()=>{for(const url of ['https://vendor.example/items/123?option=blue','https://gknest.org','https://www.gknest.org/index.html']){const {w,dom}=await adminBrowser([sampleRequisition({url})]);try{w.document.querySelector('#purchase-board button').click();const body=w.document.querySelector('#purchase-detail-body'),link=body.querySelector('a');if(url.includes('vendor.example')){assert.equal(link.href,url);assert.equal(link.target,'_blank');assert.equal(link.hasAttribute('data-external'),true);assert.equal(body.querySelector('.purchase-item-url').textContent,url);}else{assert.equal(link,null);assert.match(body.textContent,/Item link needs correction/);}assert.equal(body.querySelector('[name="itemUrl"]').value,url);}finally{dom.window.close();}}});
test('requester and inventory directors can correct item links; discussion participants cannot change another request',()=>{const {ctx,records}=harness();ctx.purchaseCreate_(student,{id,title:'Test item',reason:'Needed',quantity:1,divisions:['ALL'],fund:'CTE',url:'https://gknest.org'});assert.equal(ctx.purchaseItemLink_({...student,email:'leader@example.test',allDivisionLeadership:true},{id,revision:1,url:'https://vendor.example/item'}).status,403);assert.equal(ctx.purchaseItemLink_(student,{id,revision:1,url:'javascript:alert(1)'}).status,400);assert.equal(ctx.purchaseItemLink_(student,{id,revision:1,url:'https://vendor.example/item'}).status,200);assert.equal(records.PurchaseBoardWeb[0].url,'https://vendor.example/item');assert.equal(records.PurchaseBoardWeb[0].itemLinkHistory[0].from,'https://gknest.org');assert.equal(ctx.purchaseItemLink_(admin,{id,revision:1,url:'https://vendor.example/new'}).status,409);assert.equal(ctx.purchaseItemLink_(admin,{id,revision:2,url:''}).status,200);});
const secondId='22345678-1234-4234-8234-123456789012',thirdId='32345678-1234-4234-8234-123456789012';
function listHarness(){const h=harness();h.ctx.purchaseListPersist_=l=>{const {items,events,_pendingItem,_pendingEvent,...meta}=l;h.ctx.purchaseSave_('PurchaseListsWeb',meta);if(_pendingItem)h.ctx.purchaseSave_('PurchaseListItemsWeb',_pendingItem);h.ctx.purchaseSave_('PurchaseListEventsWeb',_pendingEvent);};return h;}
const inventoryLeader={...student,name:'Inventory One',groups:['all-leadership','inventory','division:1']},otherInventory={...student,email:'second@example.test',name:'Inventory Two',groups:['all-leadership','inventory','division:2']};
test('requested-items actions advance unknown prices, table, archive and restore without discussion editing',()=>{const {ctx,records}=harness();ctx.purchaseCreate_(student,{id,title:'Shared motors',reason:'Needed',quantity:2,divisions:['1'],fund:'CTE'});let revision=1;for(const change of ['advance','table','archive','restore']){assert.equal(ctx.purchaseRequestAction_(admin,{id,revision:revision++,change}).status,200);}assert.equal(records.PurchaseBoardWeb[0].stage,'tabled');assert.match(records.PurchaseBoardWeb[0].history.at(-1).action,/Restored/);assert.equal(ctx.purchaseRequestAction_(student,{id,revision,change:'advance'}).status,403);assert.equal(ctx.purchaseRequestAction_(admin,{id,revision:1,change:'advance'}).status,409);});
test('purchased items are timestamped and archived, stock reorders create a new idempotent request',()=>{const {ctx,records}=harness();ctx.purchaseCreate_(student,{id,title:'Stock motors',reason:'Needed',quantity:2,unitCost:12.5,divisions:['1'],fund:'CTE'});assert.equal(ctx.purchaseRequestAction_(admin,{id,revision:1,change:'stock'}).status,200);assert.equal(ctx.purchaseRequestAction_(student,{id,revision:2,change:'purchased',day:'2026-10-30'}).status,403);assert.equal(ctx.purchaseRequestAction_(admin,{id,revision:2,change:'purchased',day:'2026-10-30'}).status,200);const original=records.PurchaseBoardWeb[0];assert.equal(original.stage,'archived');assert.ok(original.purchasedAt);assert.equal(original.archivedAt,original.purchasedAt);assert.equal(original.stock,true);assert.equal(ctx.purchaseRequestAction_(admin,{id,revision:3,change:'restore'}).status,400);const reorder={id,change:'reorder',newId:secondId};assert.equal(ctx.purchaseRequestAction_(student,reorder).status,200);assert.equal(ctx.purchaseRequestAction_(student,reorder).status,200);assert.equal(records.PurchaseBoardWeb.length,2);assert.equal(records.PurchaseBoardWeb[1].sourceStockId,id);assert.equal(records.PurchaseBoardWeb[1].stage,'discussion');assert.equal(records.PurchaseBoardWeb[1].unitCost,12.5);});
test('collaborators add to their leadership level but only item authors, managers, assistants and admin edit others items',()=>{const {ctx,records}=listHarness();assert.equal(ctx.purchaseListDispatch_(inventoryLeader,{operation:'list-create',id,name:'Shared inventory',description:'Replenishment',group:'inventory'}).status,200);assert.equal(ctx.purchaseListDispatch_({...inventoryLeader,groups:['division:1']},{operation:'list-create',id:thirdId,name:'Forbidden',description:'',group:'inventory'}).status,403);const add={operation:'list-item-add',id,revision:1,itemId:secondId,title:'Motors',reason:'Stock up',quantity:2,unitCost:12.5,url:'https://vendor.example/item'};assert.equal(ctx.purchaseListDispatch_(otherInventory,add).status,200);assert.equal(ctx.purchaseListDispatch_(otherInventory,add).status,200);assert.equal(records.PurchaseListEventsWeb.length,2);const edit={...add,operation:'list-item-edit',revision:2,quantity:3};assert.equal(ctx.purchaseListDispatch_(inventoryLeader,edit).status,403);assert.equal(ctx.purchaseListDispatch_(otherInventory,edit).status,200);assert.equal(ctx.purchaseListDispatch_({...student,name:'Assistant',listManager:true,groups:['managers']},{...edit,revision:3,quantity:4}).status,200);assert.equal(records.PurchaseListItemsWeb[0].quantity,4);const publicList=ctx.purchaseListPublic_(inventoryLeader,ctx.purchaseLists_()[0]);assert.equal(publicList.items[0].canEdit,false);assert.equal(JSON.stringify(publicList).includes('@'),false);assert.equal(publicList.events.at(-1).author,'Assistant');assert.equal(publicList.events.at(-1).before.quantity,3);assert.equal(publicList.events.at(-1).after.quantity,4);});
test('removed lists and items retain history and restore safely, creators cannot remove other authors items by deleting their list',()=>{const {ctx,records}=listHarness();ctx.purchaseListDispatch_(inventoryLeader,{operation:'list-create',id,name:'Shared',description:'',group:'inventory'});ctx.purchaseListDispatch_(otherInventory,{operation:'list-item-add',id,revision:1,itemId:secondId,title:'Motor',reason:'',quantity:1,unitCost:null,url:''});assert.equal(ctx.purchaseListDispatch_(inventoryLeader,{operation:'list-remove',id,revision:2}).status,403);assert.equal(ctx.purchaseListDispatch_(otherInventory,{operation:'list-item-remove',id,revision:2,itemId:secondId}).status,200);assert.ok(records.PurchaseListItemsWeb[0].removedAt);assert.equal(ctx.purchaseListDispatch_(inventoryLeader,{operation:'list-remove',id,revision:3}).status,200);assert.ok(records.PurchaseListsWeb[0].removedAt);assert.equal(records.PurchaseListItemsWeb.length,1);assert.equal(records.PurchaseListEventsWeb.length,4);assert.equal(ctx.purchaseListDispatch_(inventoryLeader,{operation:'list-restore',id,revision:4}).status,200);assert.equal(records.PurchaseListsWeb[0].removedAt,'');assert.equal(ctx.purchaseListVisible_({...student,groups:['division:7']},records.PurchaseListsWeb[0]),false);});
test('list edits, item updates and audit append are one literal Sheets batch',()=>{const {ctx}=harness(),writes=[],sheets={PurchaseListsWeb:{getSheetId:()=>11,getLastRow:()=>1,getMaxRows:()=>1000},PurchaseListItemsWeb:{getSheetId:()=>12,getLastRow:()=>1,getMaxRows:()=>1000},PurchaseListEventsWeb:{getSheetId:()=>13,getLastRow:()=>1,getMaxRows:()=>1000}};ctx.purchaseSheet_=name=>sheets[name];ctx.SpreadsheetApp={flush(){}};ctx.Sheets={Spreadsheets:{batchUpdate:(body,id)=>writes.push({body,id})}};ctx.purchaseListPersist_({id,revision:2,name:'List',items:[],events:[],_pendingItem:{id:secondId,listId:id,title:'Motor'},_pendingEvent:{id:thirdId,listId:id,action:'Added item',author:'Example'}});assert.equal(writes.length,1);assert.equal(writes[0].id,'manager');assert.equal(writes[0].body.requests.length,3);for(const request of writes[0].body.requests){assert.equal(request.updateCells.fields,'userEnteredValue');assert.equal(typeof request.updateCells.rows[0].values[1].userEnteredValue.stringValue,'string');}assert.equal(JSON.stringify(writes).includes('formulaValue'),false);});
test('successful purchase processing timestamps and archives linked requested items while retaining stock designation',()=>{const {ctx,records}=commitHarness();const item={id:secondId,revision:1,title:'Stock motors',reason:'For build',url:'',quantity:2,unitCost:5,shipping:0,fund:'CTE',divisions:['1'],stage:'requisition',stock:true,history:[]};records.PurchaseBoardWeb.push(item);ctx.purchaseLinked_=()=>[structuredClone(records.PurchaseBoardWeb[0])];assert.equal(ctx.purchaseCommit_(admin,{id}).saved,true);assert.equal(records.PurchaseBoardWeb[0].stage,'archived');assert.ok(records.PurchaseBoardWeb[0].purchasedAt);assert.equal(records.PurchaseBoardWeb[0].purchasedDate,'2026-10-30');assert.equal(records.PurchaseBoardWeb[0].stock,true);assert.match(records.PurchaseBoardWeb[0].history.at(-1).action,/automatically archived/);});
async function workspaceBrowser(){const dom=new JSDOM(fs.readFileSync('purchasing.html','utf8'),{url:'https://gknest.org/purchasing',runScripts:'outside-only'}),w=dom.window;w.NestAuth={identity:{signedIn:true},ready:Promise.resolve()};w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;};const data={access:{admin:true,manager:true,canTriage:true,periods:['1','2','CTSO']},requests:[sampleRequisition({stage:'discussion',canTriage:true,canEditItem:true})],budget:{balance:2484.55},listGroups:[{id:'inventory',name:'Inventory directors'}],lists:[{id:secondId,revision:1,name:'Consumables',description:'Shared stock',group:'inventory',groupLabel:'Inventory directors',author:'Director One',canEdit:true,canRemove:true,items:[{id:thirdId,title:'Fasteners',reason:'Needed',quantity:5,unitCost:3,author:'Director Two',canEdit:false}],events:[{id:'event',action:'Added list item',author:'Director Two',at:'2026-10-30T17:00:00Z',before:{},after:{title:'Fasteners'}}]}],workspaceHistory:[{id:'event',kind:'list',item:'Consumables',action:'Added list item',author:'Director Two',at:'2026-10-30T17:00:00Z',before:{},after:{title:'Fasteners'}}],runs:[],asbRequests:[],asbActions:[]},calls=[];w.fetch=async(url,opts)=>{const b=opts.body?JSON.parse(opts.body):{operation:'view'};calls.push(b);if(b.operation==='request-action'&&b.change==='advance')data.requests[0].stage='requisition';return {ok:true,status:200,json:async()=>b.operation==='view'?structuredClone(data):b.operation==='admin'?{options:{vendors:[],foodTypes:['No.','Yes: CTE'],previous:[]}}:{saved:true}};};w.eval(fs.readFileSync('js/purchasing.js','utf8'));w.eval(fs.readFileSync('js/purchase-workspace.js','utf8'));await new Promise(r=>setTimeout(r,25));return {dom,w,calls,data};}
test('standalone requested-items queue advances items without opening the discussion board',async()=>{const {w,dom,calls}=await workspaceBrowser();try{assert.equal(w.document.querySelector('#purchase-checkout').hidden,false);w.document.querySelector('[data-workspace=items]').click();assert.equal(w.document.querySelector('#purchase-requested').hidden,false);assert.equal(w.document.querySelector('#purchase-discussion').hidden,true);const placement=w.document.querySelector('#purchase-requested-items .purchase-placement select');assert.ok(placement);assert.deepEqual([...placement.options].map(x=>x.value),['','advance','table','archive','stock']);assert.equal([...w.document.querySelectorAll('#purchase-requested-items button')].some(b=>b.textContent==='Move to purchase list'),false);placement.value='advance';placement.dispatchEvent(new w.Event('change',{bubbles:true}));await new Promise(r=>setTimeout(r,25));assert.equal(calls.find(x=>x.operation==='request-action').change,'advance');assert.match(w.document.querySelector('#purchase-requested-items').textContent,/On purchase list/);assert.ok(w.document.querySelector('#purchase-requisition-list input[type="checkbox"]'));}finally{dom.window.close();}});
test('collaborative lists show item-level edit permissions, history, and clear every private workspace on logout',async()=>{const {w,dom}=await workspaceBrowser();try{const lists=w.document.querySelector('#purchase-collaborative-lists');assert.match(lists.textContent,/Consumables/);assert.match(lists.textContent,/Fasteners/);const item=lists.querySelector('.purchase-list-item');assert.equal([...item.querySelectorAll('button')].some(x=>x.textContent==='Remove item'),false);assert.match(w.document.querySelector('#purchase-workspace-history').textContent,/Director Two/);w.NestAuth.identity.signedIn=false;w.document.dispatchEvent(new w.Event('nest-auth-change'));assert.equal(lists.textContent,'');assert.equal(w.document.querySelector('#purchase-workspace-history').textContent,'');assert.equal(w.document.querySelector('#purchase-requested-items').textContent,'');assert.equal(w.document.querySelector('#purchase-stock-items').textContent,'');assert.equal(w.document.querySelector('#purchase-list-group').options.length,0);}finally{dom.window.close();}});
test('removed collaborative items can be restored by their author with a new audit event',()=>{const {ctx,records}=listHarness();ctx.purchaseListDispatch_(inventoryLeader,{operation:'list-create',id,name:'Shared',description:'',group:'inventory'});ctx.purchaseListDispatch_(otherInventory,{operation:'list-item-add',id,revision:1,itemId:secondId,title:'Motor',reason:'',quantity:1,unitCost:5,url:''});ctx.purchaseListDispatch_(otherInventory,{operation:'list-item-remove',id,revision:2,itemId:secondId});assert.equal(ctx.purchaseListDispatch_(inventoryLeader,{operation:'list-item-restore',id,revision:3,itemId:secondId}).status,403);assert.equal(ctx.purchaseListDispatch_(otherInventory,{operation:'list-item-restore',id,revision:3,itemId:secondId}).status,200);assert.equal(records.PurchaseListItemsWeb[0].removedAt,'');assert.equal(records.PurchaseListEventsWeb.at(-1).action,'Restored list item');});
test('list histories grow as separate records without rewriting a single growing history cell',()=>{const {ctx,records}=listHarness();ctx.purchaseListDispatch_(inventoryLeader,{operation:'list-create',id,name:'Shared',description:'',group:'inventory'});for(let n=1;n<=60;n++)assert.equal(ctx.purchaseListDispatch_(inventoryLeader,{operation:'list-edit',id,revision:n,name:'Shared '+n,description:'Edited purpose '+n}).status,200);assert.equal(records.PurchaseListEventsWeb.length,61);assert.equal(records.PurchaseListsWeb.length,1);assert.equal(Object.hasOwn(records.PurchaseListsWeb[0],'events'),false);assert.equal(Object.hasOwn(records.PurchaseListsWeb[0],'items'),false);});
test('financial school-year classification follows the existing August rollover',()=>{const {ctx}=harness();assert.equal(ctx.purchaseSchoolYear_('2026-07-31'),'25_26');assert.equal(ctx.purchaseSchoolYear_('2026-08-01'),'26_27');assert.equal(ctx.purchaseSchoolYear_('10/29/2026 11:30:00'),'26_27');assert.equal(ctx.purchaseSchoolYear_('invalid'),'');assert.equal(ctx.purchaseFinancialHistory_(student,{}).status,403);assert.equal(ctx.purchaseFinancialHistory_(admin,{year:'26_28'}).status,400);assert.equal(ctx.purchaseFinancialHistory_(admin,{year:'27_28'}).status,400);});
test('purchase archive defaults to the verified current annual ledger and filters ASB requests by school year',()=>{const {ctx}=harness();let selectedYear='',writes=0;ctx.purchaseFinancialLog_=()=>[];ctx.purchaseFinancialYears_=()=>[{id:'26_27',label:'2026–2027'},{id:'25_26',label:'2025–2026'}];ctx.resolveCurrentBudgetFile_=year=>{selectedYear=year;return {getId:()=> 'annual-budget',getName:()=> 'Verified teacher budget',getUrl:()=> 'https://docs.google.com/spreadsheets/d/annual-budget'};};ctx.SpreadsheetApp={openById:()=>({})};ctx.findBudgetTabAndHeaders_=()=>({headerRow:1,headerMap:{Date:1,Vendor:2,Description:3,Amount:4,Total:5},sheet:{getLastRow:()=>3,getLastColumn:()=>5,getRange:()=>({getValues:()=>selectedYear==='26_27'?[['10/29/2026','Current vendor','Equipment','15.45',15.45],['06/30/2025','Refund vendor','Return recorded in current ledger',-2,-2]]:[['05/06/2026','Prior vendor','Prior equipment',20,20],['','','','','']],getRichTextValues:()=>[[null,null,null,null,null],[null,null,null,null,null]],setValues:()=>{writes++;}})}});ctx.purchaseAsbPublic_=()=>[{day:'10/30/2026',vendor:'Current ASB'},{day:'5/6/2026 16:08:15',vendor:'Prior ASB'}];const current=ctx.purchaseFinancialHistory_(admin,{});assert.equal(current.year,'26_27');assert.equal(selectedYear,'26_27');assert.equal(current.purchases.length,2);assert.equal(current.purchases[0].vendor,'Current vendor');assert.equal(current.asbRequests.length,1);assert.equal(current.asbRequests[0].vendor,'Current ASB');const old=ctx.purchaseFinancialHistory_(admin,{year:'25_26'});assert.equal(old.purchases[0].vendor,'Prior vendor');assert.equal(old.asbRequests[0].vendor,'Prior ASB');assert.equal(writes,0);});
test('historical form-record fallback is explicit and only returns the selected school year',()=>{const {ctx}=harness();ctx.purchaseFinancialLog_=()=>[{id:'a',year:'25_26',day:'2026-05-06',vendor:'Old vendor',type:'New Purchase'},{id:'b',year:'26_27',day:'2026-10-29',vendor:'Current vendor',type:'New Purchase'}];ctx.purchaseFinancialYears_=()=>[{id:'26_27'},{id:'25_26'}];ctx.resolveCurrentBudgetFile_=()=>{throw Error('No matching annual sheet');};ctx.purchaseAsbPublic_=()=>[];const result=ctx.purchaseFinancialHistory_(admin,{year:'25_26'});assert.equal(result.purchases.length,1);assert.equal(result.purchases[0].vendor,'Old vendor');assert.match(result.warning,/could not be verified/);assert.equal(result.source,'Saved BudgetLog responses');});
test('current purchase-record area excludes prior-school-year website runs and ASB requests',()=>{const {ctx,records}=harness();ctx.purchaseBudget_=()=>({year:'26_27',balance:2484.55});ctx.purchaseAsbPublic_=()=>[{day:'5/6/2026',vendor:'Old'},{day:'10/29/2026',vendor:'Current'}];records.PurchaseRunsWeb.push({id:'old',state:'complete',createdAt:'2026-05-06T17:00:00Z',draft:{day:'2026-05-06',type:'New Purchase',vendor:'Old',amount:20}},{id:'new',state:'complete',createdAt:'2026-10-29T17:00:00Z',draft:{day:'2026-10-29',type:'New Purchase',vendor:'Current',amount:15.45}});const result=ctx.purchaseView_(admin);assert.equal(result.runs.length,1);assert.equal(result.runs[0].id,'new');assert.equal(result.asbRequests.length,1);assert.equal(result.asbRequests[0].vendor,'Current');});
test('purchase-year tab defaults to current year, changes years on request, and removes admin affidavits',async()=>{const {w,dom}=await workspaceBrowser();try{const original=w.fetch;w.fetch=async(url,opts)=>{const body=opts.body?JSON.parse(opts.body):{};if(body.operation!=='purchase-history')return original(url,opts);const year=body.year||'26_27';return {ok:true,status:200,json:async()=>({year,currentYear:'26_27',years:[{id:'26_27',label:'2026–2027'},{id:'25_26',label:'2025–2026'}],purchases:[{day:year==='26_27'?'2026-10-29':'2026-05-06',vendor:year==='26_27'?'Current vendor':'Prior vendor',receiptAmount:15.45,total:15.45,type:'Purchase',source:'District budget',description:'Equipment'}],asbRequests:[],source:'Verified teacher budget'})};};w.document.querySelector('[data-panel="records"]').click();await new Promise(r=>setTimeout(r,20));assert.equal(w.document.querySelector('#purchase-financial-year').value,'26_27');assert.match(w.document.querySelector('#purchase-financial-purchases').textContent,/Current vendor/);const year=w.document.querySelector('#purchase-financial-year');year.value='25_26';year.dispatchEvent(new w.Event('change',{bubbles:true}));await new Promise(r=>setTimeout(r,20));assert.match(w.document.querySelector('#purchase-financial-purchases').textContent,/Prior vendor/);assert.equal(w.document.querySelector('#purchase-financial-purchases').textContent.includes('Current vendor'),false);assert.equal(w.document.querySelectorAll('#purchase-admin-form input[type="checkbox"]').length,0);assert.equal(w.document.querySelectorAll('#purchase-asb-requests input[type="checkbox"]').length,0);assert.equal([...w.document.querySelectorAll('#purchase-requested-items input[type="checkbox"]')].length,0);}finally{dom.window.close();}});
test('executive signing mockup freezes the background, captures sample identity and drawing, and sends no network requests',async()=>{const {w,dom,calls}=await adminBrowser();try{w.NestAuth.identity.username='mpenalver';w.requestAnimationFrame=fn=>fn();const canvas=w.document.querySelector('#purchase-signature-demo-canvas');canvas.getBoundingClientRect=()=>({left:0,top:0,width:400,height:200});canvas.getContext=()=>({scale(){},fillRect(){},beginPath(){},moveTo(){},lineTo(){},stroke(){}});canvas.toDataURL=()=> 'data:image/png;base64,c2FtcGxl';w.eval(fs.readFileSync('js/signature-demo.js','utf8'));const type=w.document.querySelector('#purchase-type');assert.equal(w.document.querySelector('#purchase-asb-approvals').hidden,true);type.value='ASB Purchase Request';type.dispatchEvent(new w.Event('change',{bubbles:true}));assert.equal(w.document.querySelector('#purchase-asb-approvals').hidden,false);const count=calls.length;w.document.querySelector('#purchase-signature-demo-start').click();assert.equal(w.document.querySelector('#purchase-signature-demo-banner').hidden,false);w.document.querySelector('#purchase-signature-demo-banner button').click();assert.equal(w.document.querySelector('#purchase-signature-demo-dialog').open,true);assert.equal(w.document.body.style.overflow,'hidden');assert.match(w.document.querySelector('#purchase-signature-demo-identity').textContent,/mpenalver/);canvas.dispatchEvent(new w.MouseEvent('pointerdown',{clientX:10,clientY:20,bubbles:true}));canvas.dispatchEvent(new w.MouseEvent('pointermove',{clientX:180,clientY:60,bubbles:true}));canvas.dispatchEvent(new w.MouseEvent('pointerup',{clientX:320,clientY:80,bubbles:true}));w.document.querySelector('#purchase-signature-demo-save').click();assert.equal(w.document.querySelector('#purchase-signature-demo-dialog').open,false);assert.equal(w.document.body.style.overflow,'');assert.match(w.document.querySelector('#purchase-signature-demo-result').textContent,/mpenalver/);assert.match(w.document.querySelector('#purchase-signature-demo-banner').textContent,/Chief Financial Officer/);assert.equal(calls.length,count);w.NestAuth.identity.signedIn=false;w.document.dispatchEvent(new w.Event('nest-auth-change'));assert.equal(w.document.querySelector('#purchase-signature-demo-panel').hidden,true);assert.equal(w.document.querySelector('#purchase-signature-demo-result').textContent,'');}finally{dom.window.close();}});

 test('Purchasing defaults to the form while Item Management groups requests, lists, stock and list archives',async()=>{const {w,dom}=await workspaceBrowser();try{const d=w.document,click=s=>d.querySelector(s).click(),visible=id=>!d.querySelector(id).hidden;assert.equal(d.querySelectorAll('.purchase-primary-tabs [role="tab"]').length,5);assert.ok(visible('#purchase-checkout'));assert.equal(d.querySelector('#purchase-equipment iframe'),null);click('[data-workspace="items"]');assert.ok(visible('#purchase-requested'));click('[data-panel="stock"]');assert.ok(visible('#purchase-stock'));click('[data-list-view="removed"]');assert.equal(d.querySelector('#purchase-lists-filter').value,'removed');assert.equal(d.querySelector('[data-list-view="removed"]').textContent,'List archive');click('[data-workspace="purchasing"]');assert.ok(visible('#purchase-checkout'));click('[data-workspace="items"]');assert.equal(d.querySelector('[data-list-view="removed"]').getAttribute('aria-selected'),'true');click('[data-workspace="history"]');assert.ok(visible('#purchase-history'));assert.ok([...d.querySelectorAll('[data-tab-group]')].every(e=>e.hidden));const primary=d.querySelector('[data-workspace="history"]');primary.focus();primary.dispatchEvent(new w.KeyboardEvent('keydown',{key:'Home',bubbles:true}));assert.equal(d.activeElement.dataset.workspace,'purchasing');assert.ok(visible('#purchase-checkout'));assert.equal(d.querySelectorAll('.purchase-panel:not([hidden])').length,1);assert.match(fs.readFileSync('inventory.html','utf8'),/href="\/purchasing#equipment"/);assert.match(fs.readFileSync('inventory-management.html','utf8'),/url=\/purchasing#equipment/);}finally{dom.window.close();}});

