test('placement menu honors permissions, archive restoration and purchase-processing locks',async()=>{const {w,dom,data}=await workspaceBrowser();try{const row=data.requests[0];row.canTriage=false;await w.NestPurchasing.reload();assert.equal(w.document.querySelector('#purchase-requested-items .purchase-placement'),null);row.canTriage=true;row.purchaseState='review-required';await w.NestPurchasing.reload();assert.equal(w.document.querySelector('#purchase-requested-items .purchase-placement'),null);row.purchaseState='';row.stage='archived';row.stock=true;await w.NestPurchasing.reload();let menu=w.document.querySelector('#purchase-archived-items .purchase-placement select');assert.deepEqual([...menu.options].map(o=>o.value),['','restore','unstock']);row.purchasedAt='2026-10-30T17:00:00Z';await w.NestPurchasing.reload();menu=w.document.querySelector('#purchase-archived-items .purchase-placement select');assert.deepEqual([...menu.options].map(o=>o.value),['','unstock']);const stock=w.document.querySelector('#purchase-stock-items .purchase-placement select');assert.ok([...stock.options].some(o=>o.value==='reorder'));}finally{dom.window.close();}});

test('service item transfers are validated as a batch and stable IDs deduplicate retries without changing progressed requests',()=>{const {ctx,records}=harness();const row={id,title:'Chair caster',quantity:4,unitCost:5.25,url:'https://supplier.example/caster',notes:'Replacement parts',fund:'CTE',division:'1'},actor={...student};const r={operation:'service-import',ticketId:secondId,items:[row]};assert.equal(ctx.purchaseDispatch_(actor,r).status,200);assert.equal(records.PurchaseBoardWeb.length,1);assert.equal(records.PurchaseBoardWeb[0].sourceService.ticketId,secondId);records.PurchaseBoardWeb[0].stage='requisition';assert.equal(ctx.purchaseDispatch_(actor,r).status,200);assert.equal(records.PurchaseBoardWeb.length,1);assert.equal(records.PurchaseBoardWeb[0].stage,'requisition');assert.equal(ctx.purchaseDispatch_(actor,{...r,ticketId:thirdId}).status,409);const bad={...row,id:thirdId,division:'2'};assert.equal(ctx.purchaseDispatch_(actor,{...r,items:[bad]}).status,400);assert.equal(records.PurchaseBoardWeb.length,1);const clean=harness();assert.equal(clean.ctx.purchaseServiceImport_(actor,{...r,items:[row,{...bad,quantity:-1}]}).status,400);assert.equal(clean.records.PurchaseBoardWeb.length,0);});
