test('native practice commit is district-only, sends once and never enters fiscal processing',()=>{for(const failure of [false,true]){const {ctx,records,writes}=harness();const draft={type:'Practice Purchase — email preview only',day:'2026-11-02',vendor:'Amazon',description:'Practice example',amount:12.34,shipping:0,taxed:'Yes',foodType:'No.',attendees:[],links:[],items:[],vendorDetails:''};records.PurchaseRunsWeb.push({id,email:admin.email,state:'preview',draft,expires:Date.now()+60000,receiptUrl:'private receipt'});ctx.purchaseOptions_=()=>({types:[draft.type],foodTypes:['No.']});ctx.SpreadsheetApp={openById(){throw Error('Fiscal spreadsheet accessed')}};ctx.purchaseBudget_=()=>{throw Error('Budget accessed')};ctx.purchaseLinked_=()=>{throw Error('Linked items changed')};ctx.processFormResponse=()=>{throw Error('Fiscal processor called')};let sends=0;ctx.processPracticePurchase_=e=>{sends++;assert.equal(e.values[1],draft.type);assert.equal(e.values[40],'private receipt');if(failure)throw Error('uncertain mail');return {previewTo:admin.email,productionTo:'clerk@example.test'};};assert.equal(ctx.purchaseCommit_({...admin,email:'astramario@gmail.com'},{id}).status,403);assert.equal(ctx.purchaseCommit_(student,{id}).status,403);const result=ctx.purchaseCommit_(admin,{id});assert.equal(result.practice,true);assert.equal(result.saved,!failure);ctx.purchaseCommit_(admin,{id});assert.equal(sends,1);assert.ok(writes.every(x=>x==='PurchaseRunsWeb'));assert.equal(records.PurchaseRunsWeb[0].state,failure?'practice-review-required':'practice-complete');assert.equal(records.PurchaseBoardWeb.length,0);}});

test('school bridge denies private purchase form to personal owner accounts and roster members',()=>{const source=fs.readFileSync('google-spinner/Purchasing.js','utf8');for(const email of ['astramario@gmail.com','mario@memberhq.net','student@example.test','mpenalver@bethelsd.org']){const ctx=staffContext({OWNER_EMAILS:['mpenalver@bethelsd.org','astramario@gmail.com','mario@memberhq.net'],email_:s=>s.toLowerCase(),authSession_:()=>({email,username:'Example'}),PropertiesService:{getScriptProperties:()=>({})}});vm.runInContext(source,ctx);let forwarded=0;ctx.purchasingBudgetRequest_=()=>{forwarded++;return {status:200}};for(const operation of ['admin','preview','commit','food-document','attendance','asb-commit'])assert.equal(ctx.purchasingWork_({operation}).status,email==='mpenalver@bethelsd.org'?200:403);assert.equal(forwarded,email==='mpenalver@bethelsd.org'?6:0);}});

test('practice email confirmation retains native form values and posts only the saved preview id',async()=>{const {w,dom,calls}=await adminBrowser();try{const type='Practice Purchase — email preview only',d=w.document,form=d.querySelector('#purchase-admin-form');assert.ok([...form.elements.type.options].some(x=>x.value===type));form.elements.type.value=type;form.elements.vendor.value='Amazon';form.elements.description.value='Example only';let post=[];w.fetch=async(url,opts)=>{const body=opts.body?JSON.parse(opts.body):{operation:'view'};post.push(body);const data=body.operation==='preview'?{preview:{id,type,vendor:'Amazon',amount:12.34,recipient:'clerk@example.test',balance:2484.55,estimatedImpact:0,receiptName:'Penalver_2026.11_12.34',attendeeCount:0,linked:[],asbTotal:null,notice:'Practice only'}}:body.operation==='commit'?{saved:true,practice:true,message:'Practice email sent only to you.'}:{access:{admin:true,manager:true,periods:[]},requests:[],runs:[]};return {ok:true,status:200,json:async()=>data};};form.dispatchEvent(new w.Event('submit',{bubbles:true,cancelable:true}));await new Promise(r=>setTimeout(r,20));assert.equal(d.querySelector('#purchase-commit').textContent,'Email practice preview to me');d.querySelector('#purchase-commit').click();await new Promise(r=>setTimeout(r,30));assert.deepEqual(post.find(x=>x.operation==='commit'),{operation:'commit',id});assert.equal(form.elements.description.value,'Example only');assert.equal(form.elements.type.value,type);assert.match(d.querySelector('#purchase-message').textContent,/Practice email sent/);}finally{dom.window.close();}});

test('purchase review is modal, waits for explicit confirmation, and retains visible sending and success status',async()=>{const {w,dom}=await adminBrowser();try{const d=w.document,form=d.querySelector('#purchase-admin-form'),dialog=d.querySelector('#purchase-preview');let sends=0,finish;w.fetch=async(url,opts)=>{const b=opts.body?JSON.parse(opts.body):{operation:'view'};if(b.operation==='preview')return {ok:true,json:async()=>({preview:{id,type:'New Purchase',vendor:'Amazon',amount:12.34,recipient:'clerk@example.test',balance:2484.55,estimatedImpact:12.34,receiptName:'Receipt.pdf',attendeeCount:0,linked:[],asbTotal:null}})};if(b.operation==='commit'){sends++;return new Promise(resolve=>{finish=()=>resolve({ok:true,json:async()=>({saved:true,state:'complete',message:'Processed.'})});});}return {ok:true,json:async()=>({access:{admin:true,manager:true,periods:[]},requests:[],runs:[]})};};form.dispatchEvent(new w.Event('submit',{bubbles:true,cancelable:true}));await new Promise(r=>setTimeout(r,20));assert.equal(dialog.tagName,'DIALOG');assert.equal(dialog.open,true);assert.equal(d.body.style.overflow,'hidden');assert.equal(sends,0);d.querySelector('#purchase-commit').click();await new Promise(r=>setTimeout(r,10));assert.equal(sends,1);assert.match(d.querySelector('#purchase-submit-title').textContent,/Recording purchase and sending/);assert.equal(d.querySelector('#purchase-review-cancel').disabled,true);const escape=new w.Event('cancel',{cancelable:true});dialog.dispatchEvent(escape);assert.equal(escape.defaultPrevented,true);d.querySelector('#purchase-commit').click();assert.equal(sends,1);finish();await new Promise(r=>setTimeout(r,30));assert.equal(dialog.open,true);assert.equal(d.querySelector('#purchase-submit-feedback').dataset.state,'success');assert.match(d.querySelector('#purchase-submit-title').textContent,/receipt email sent/);assert.equal(d.querySelector('#purchase-review-cancel').disabled,false);d.querySelector('#purchase-review-cancel').click();assert.equal(dialog.open,false);assert.equal(d.body.style.overflow,'');}finally{dom.window.close();}});

test('a timed-out confirmation checks saved status without resending and identifies a completed practice email',async()=>{const {w,dom}=await adminBrowser();try{const d=w.document,type='Practice Purchase — email preview only';let sends=0,checks=0;d.querySelector('#purchase-type').value=type;w.fetch=async(url,opts)=>{const b=opts.body?JSON.parse(opts.body):{operation:'view'};if(b.operation==='preview')return {ok:true,json:async()=>({preview:{id,type,vendor:'Amazon',amount:12.34,recipient:'clerk@example.test',balance:2484.55,estimatedImpact:0,receiptName:'Receipt.pdf',attendeeCount:0,linked:[],asbTotal:null}})};if(b.operation==='commit'){sends++;throw Error('Timed out');}checks++;return {ok:true,json:async()=>({runs:[{id,state:'practice-complete',message:'Practice sent'}]})};};d.querySelector('#purchase-admin-form').dispatchEvent(new w.Event('submit',{bubbles:true,cancelable:true}));await new Promise(r=>setTimeout(r,20));d.querySelector('#purchase-commit').click();await new Promise(r=>setTimeout(r,30));assert.equal(sends,1);assert.equal(checks,1);assert.equal(d.querySelector('#purchase-preview').open,true);assert.match(d.querySelector('#purchase-submit-title').textContent,/Practice email sent/);assert.equal(d.querySelector('#purchase-status-check').hidden,true);}finally{dom.window.close();}});

test('food question leads the form and switches vendor dropdowns with a custom vendor escape hatch',async()=>{const {w,dom}=await adminBrowser([],['Vendor','🍕 Food Vendor']);try{const d=w.document,f=d.querySelector('#purchase-admin-form'),menu=f.elements.vendor;assert.equal(f.firstElementChild.querySelector('select').name,'foodType');assert.ok([...menu.options].some(x=>x.value==='Vendor'));assert.ok(![...menu.options].some(x=>x.value==='🍕 Food Vendor'));menu.value='Vendor';f.elements.foodType.value='Yes: CTE';f.elements.foodType.dispatchEvent(new w.Event('change',{bubbles:true}));assert.equal(menu.value,'');assert.ok([...menu.options].some(x=>x.value==='🍕 Food Vendor'));assert.ok(![...menu.options].some(x=>x.value==='Vendor'));menu.value='__OTHER_VENDOR__';menu.dispatchEvent(new w.Event('change',{bubbles:true}));assert.equal(d.querySelector('#purchase-other-vendor-field').hidden,false);assert.equal(f.elements.vendorOther.required,true);f.elements.foodType.value='No.';f.elements.foodType.dispatchEvent(new w.Event('change',{bubbles:true}));assert.equal(d.querySelector('#purchase-other-vendor-field').hidden,true);assert.equal(f.elements.vendorOther.required,false);assert.equal(menu.value,'');await new Promise(r=>setTimeout(r,10));assert.equal(f.elements.attendees.value,'');}finally{dom.window.close();}});

test('practice email history is separated and collapsed by default without hiding actual purchases',async()=>{const runs=[{id,type:'New Purchase',state:'complete',vendor:'Actual Vendor',amount:20,at:'2026-11-02T15:00:00Z',message:'Recorded'},{id:secondId,type:'Practice Purchase — email preview only',state:'practice-complete',vendor:'Practice Vendor',amount:30,at:'2026-11-02T16:00:00Z',message:'Practice only'}];const {w,dom}=await adminBrowser([],['Vendor'],runs);try{const d=w.document;assert.match(d.querySelector('#purchase-submission-history').textContent,/Actual Vendor/);assert.doesNotMatch(d.querySelector('#purchase-submission-history').textContent,/Practice Vendor/);assert.match(d.querySelector('#purchase-practice-submissions').textContent,/Practice Vendor/);assert.equal(d.querySelector('#purchase-practice-history').open,false);assert.match(d.querySelector('#purchase-practice-summary').textContent,/\(1\)/);d.querySelector('#purchase-practice-history').open=true;await w.NestPurchasing.reload();assert.equal(d.querySelector('#purchase-practice-history').open,true);w.NestAuth.identity.signedIn=false;d.dispatchEvent(new w.Event('nest-auth-change'));assert.equal(d.querySelector('#purchase-practice-submissions').textContent,'');assert.equal(d.querySelector('#purchase-practice-history').open,false);}finally{dom.window.close();}});

