test('receipt upload fills totals from canonical, currency, and labelled filenames without mistaking dates or conflicting amounts',async()=>{const {w,dom}=await adminBrowser();try{const d=w.document,f=d.querySelector('#purchase-admin-form'),input=d.querySelector('#purchase-receipt');for(const [name,total] of [['Penalver_2026.11_310.40.pdf','310.40'],['Amazon_$1,234.56.pdf','1234.56'],['Amazon_Total_310.40.pdf','310.40'],['Amazon_310.40_2026-11-02.pdf','310.40'],['Receipt $12.pdf','12.00'],['Amazon_2026.11.pdf',null],['Amazon_10.00_12.34.pdf',null],['Receipt $12.345.pdf',null],['Receipt $1,23.45.pdf',null]]){f.elements.amount.value='9.99';Object.defineProperty(input,'files',{configurable:true,value:[new w.File(['example'],name,{type:'application/pdf'})]});input.dispatchEvent(new w.Event('change',{bubbles:true}));assert.equal(f.elements.amount.value,total||'9.99',name);assert.match(d.querySelector('#purchase-receipt-amount-status').textContent,total?/filled from the filename/:/No single purchase total/,name);}const rows=f.querySelectorAll(':scope > .purchase-columns');assert.equal(rows[0].querySelectorAll('select')[0].name,'foodType');assert.equal(rows[0].querySelectorAll('select')[1].name,'type');assert.equal(rows[1].querySelector('select').name,'vendor');assert.equal(rows[1].querySelector('input').name,'day');}finally{dom.window.close();}});

test('food choices remain populated while saved options load and the form cannot submit prematurely',async()=>{const dom=new JSDOM(fs.readFileSync('purchasing.html','utf8'),{url:'https://gknest.org/purchasing',runScripts:'outside-only'}),w=dom.window;try{w.NestAuth={identity:{signedIn:true},ready:Promise.resolve()};w.HTMLDialogElement.prototype.close=function(){this.open=false};w.HTMLDialogElement.prototype.showModal=function(){this.open=true};let complete;w.fetch=async(url,opts)=>{const b=opts.body?JSON.parse(opts.body):{operation:'view'};if(b.operation==='admin')return new Promise(resolve=>{complete=options=>resolve({ok:true,json:async()=>({options})})});return {ok:true,json:async()=>({access:{admin:true,manager:true,periods:[]},requests:[],runs:[]})};};w.eval(fs.readFileSync('js/purchasing.js','utf8'));await new Promise(r=>setTimeout(r,20));const food=w.document.querySelector('#purchase-food-type');assert.equal(food.options.length,3);assert.equal(food.disabled,true);assert.equal(w.document.querySelector('#purchase-preview-button').disabled,true);complete({vendors:['Vendor'],foodTypes:['No.','Yes: ASB','Yes: CTE'],previous:[]});await new Promise(r=>setTimeout(r,20));assert.equal(food.options.length,3);assert.equal(food.disabled,false);assert.equal(w.document.querySelector('#purchase-form-options-status').hidden,true);}finally{dom.window.close();}});

test('form choices use three targeted items and a short cache while transaction validation remains fresh',()=>{const {ctx}=harness();let opens=0,reads=0,cached='',vendor='Vendor';ctx.CONFIG.FORM_ID='purchase-form';ctx.CacheService={getScriptCache:()=>({get:()=>cached,put:(key,value,ttl)=>{assert.equal(ttl,300);cached=value;}})};ctx.SpreadsheetApp={openById(){throw Error('Normal form choices must not read headers or spreadsheets')}};ctx.FormApp={openById:id=>{assert.equal(id,'purchase-form');opens++;return {getItems(){throw Error('Normal form choices must not enumerate the whole form')},getItemById:id=>{reads++;const title=id===1421458905?'Vendor':id===1302789551?'Is this a food purchase?':'What original purchase is this related to?',values=id===1421458905?[vendor]:id===1302789551?['No.','Yes: CTE']:[];return {getTitle:()=>title,getType:()=> 'LIST',asListItem:()=>({getChoices:()=>values.map(v=>({getValue:()=>v}))})};}};}};assert.equal(ctx.purchaseCachedOptions_().vendors[0],'Vendor');assert.equal(reads,3);ctx.purchaseCachedOptions_();assert.equal(opens,1);vendor='Updated Vendor';assert.equal(ctx.purchaseOptions_().vendors[0],'Updated Vendor');assert.equal(opens,2);assert.equal(ctx.purchaseCachedOptions_().vendors[0],'Updated Vendor');ctx.purchaseCachedOptions_=()=>{throw Error('Non-administrator cache access')};assert.equal(ctx.purchaseDispatch_(student,{operation:'admin'}).status,403);});

test('verified district form becomes usable before slow workspace history finishes loading',async()=>{const dom=new JSDOM(fs.readFileSync('purchasing.html','utf8'),{url:'https://gknest.org/purchasing',runScripts:'outside-only'}),w=dom.window;let finishView;try{w.NestAuth={identity:{signedIn:true,email:'mpenalver@bethelsd.org'},ready:Promise.resolve()};w.HTMLDialogElement.prototype.close=function(){this.open=false};w.HTMLDialogElement.prototype.showModal=function(){this.open=true};const calls=[];w.fetch=async(url,opts)=>{const b=opts?.body?JSON.parse(opts.body):{operation:'view'};calls.push(b.operation);if(b.operation==='view')return new Promise(resolve=>{finishView=()=>resolve({ok:true,json:async()=>({access:{admin:true,manager:true,periods:[]},requests:[],runs:[]})})});return {ok:true,json:async()=>({access:{admin:true,manager:true,periods:[]},options:{vendors:['Vendor'],foodTypes:['No.','Yes: CTE'],previous:[]}})};};w.eval(fs.readFileSync('js/purchasing.js','utf8'));await new Promise(r=>setTimeout(r,25));const d=w.document;assert.equal(d.querySelector('#purchase-workspace').hidden,false);assert.equal(d.querySelector('#purchase-food-type').disabled,false);assert.equal(d.querySelector('#purchase-preview-button').disabled,false);assert.equal(d.querySelector('#purchase-form-options-status').hidden,true);assert.deepEqual(calls,['admin','view']);d.querySelector('#purchase-admin-form').elements.description.value='Keep my draft';finishView();await new Promise(r=>setTimeout(r,25));assert.equal(d.querySelector('#purchase-admin-form').elements.description.value,'Keep my draft');assert.equal(calls.filter(x=>x==='admin').length,1);}finally{if(finishView)finishView();await new Promise(r=>setTimeout(r,10));dom.window.close();}});
test('Amazon receipt descriptions use item quantities and titles, omit addresses/payment details, and bound long invoices',()=>{const ctx=staffContext({window:{}});vm.runInContext(fs.readFileSync('js/purchase-receipt.js','utf8'),ctx);const parse=ctx.window.NestPurchaseReceipt.amazonDescription;const result=parse([['Amazon.com order number:','private order id','Shipping Address:','PRIVATE ADDRESS','Items Ordered','Price','2 of:','Robotics wire kit','with connectors','Sold by: Example Seller','$12.34','Condition: New'],['1 of: Cardstock paper','Sold by and invoiced on behalf of: Example','Payment information','Visa last digits: 1234','PRIVATE BILLING ADDRESS']]);assert.equal(result,'2 × Robotics wire kit with connectors\n1 × Cardstock paper');assert.equal(parse([['Amazon.com','Grand Total: $10.00','PRIVATE ADDRESS']]),'');assert.equal(parse([['Another shop','1 of: Wire kit','Sold by: Shop']]),'');const long=parse([['Amazon.com',...Array.from({length:50},(_,i)=>['1 of:',`Example supply ${i} `+'long title '.repeat(30),'Sold by: Example']).flat()]]);assert.ok(long.length<2000);assert.match(long,/more item\(s\)/);});
test('receipt description fills on selection without a preview or API request and preserves edits during reading',async()=>{const {w,dom,calls}=await adminBrowser();try{const d=w.document,input=d.querySelector('#purchase-receipt'),description=d.querySelector('#purchase-admin-form [name="description"]');let resolve;w.NestPurchaseReceipt={describe:()=>new Promise(r=>{resolve=r;})};const select=name=>{const file=new w.File(['example'],name,{type:'application/pdf'});Object.defineProperty(input,'files',{configurable:true,value:[file]});input.dispatchEvent(new w.Event('change',{bubbles:true}));};const count=calls.length;select('Amazon_42.95.pdf');assert.match(d.querySelector('#purchase-receipt-description-status').textContent,/Reading/);resolve({description:'2 × Example motors',message:'Description filled from the Amazon invoice.'});await new Promise(r=>setTimeout(r,0));assert.equal(description.value,'2 × Example motors');assert.equal(calls.length,count);select('Amazon_50.00.pdf');assert.equal(description.value,'');description.value='My edited purchase purpose';description.dispatchEvent(new w.Event('input',{bubbles:true}));resolve({description:'Wrong replacement',message:'Read'});await new Promise(r=>setTimeout(r,0));assert.equal(description.value,'My edited purchase purpose');select('Amazon_60.00.pdf');assert.match(d.querySelector('#purchase-receipt-description-status').textContent,/kept/);}finally{dom.window.close();}});
test('receipt reading discards stale results after selecting another file or resetting',async()=>{const {w,dom}=await adminBrowser();try{const d=w.document,input=d.querySelector('#purchase-receipt'),description=d.querySelector('#purchase-admin-form [name="description"]'),pending=[];w.NestPurchaseReceipt={describe:()=>new Promise(r=>pending.push(r))};for(const name of ['First.pdf','Second.pdf']){Object.defineProperty(input,'files',{configurable:true,value:[new w.File(['example'],name,{type:'application/pdf'})]});input.dispatchEvent(new w.Event('change',{bubbles:true}));}pending[0]({description:'Old item',message:'Old'});await new Promise(r=>setTimeout(r,0));assert.equal(description.value,'');pending[1]({description:'Current item',message:'Current'});await new Promise(r=>setTimeout(r,0));assert.equal(description.value,'Current item');description.value='';input.dispatchEvent(new w.Event('change',{bubbles:true}));d.querySelector('#purchase-admin-form').reset();pending[2]({description:'Late item',message:'Late'});await new Promise(r=>setTimeout(r,0));assert.equal(description.value,'');}finally{dom.window.close();}});
test('confirmed purchase appears immediately and stays after close when workspace refresh is slow or stale',async()=>{const {w,dom}=await adminBrowser();try{const d=w.document,f=d.querySelector('#purchase-admin-form'),old={id:secondId,type:'New Purchase',state:'complete',vendor:'Previous vendor',amount:5,at:'2026-11-01T12:00:00Z',message:'Previously saved'};let finishRefresh,sends=0;w.fetch=async(url,opts)=>{const b=opts.body?JSON.parse(opts.body):{operation:'view'};if(b.operation==='preview')return {ok:true,json:async()=>({preview:{id,type:'New Purchase',vendor:'Newly confirmed supplier',amount:42.95,receipt:'https://drive.google.com/file/d/example/view',recipient:'clerk@example.test',balance:100,estimatedImpact:42.95,linked:[]}})};if(b.operation==='commit'){sends++;return {ok:true,json:async()=>({saved:true,state:'complete',message:'Recorded successfully'})};}return new Promise(resolve=>{finishRefresh=()=>resolve({ok:true,json:async()=>({access:{admin:true,manager:true,periods:[]},requests:[],runs:[old]})});});};f.dispatchEvent(new w.Event('submit',{bubbles:true,cancelable:true}));await new Promise(r=>setTimeout(r,10));d.querySelector('#purchase-commit').click();await new Promise(r=>setTimeout(r,10));assert.match(d.querySelector('#purchase-submission-history').textContent,/Newly confirmed supplier.*42.95/);assert.equal(d.querySelector('#purchase-review-cancel').disabled,false);d.querySelector('#purchase-review-cancel').click();assert.equal(d.querySelector('#purchase-preview').open,false);assert.equal(sends,1);finishRefresh();await new Promise(r=>setTimeout(r,15));const history=d.querySelector('#purchase-submission-history');assert.match(history.textContent,/Newly confirmed supplier/);assert.match(history.textContent,/Previous vendor/);assert.equal(history.querySelectorAll('article').length,2);w.fetch=async()=>({ok:true,json:async()=>({access:{admin:true,manager:true,periods:[]},requests:[],runs:[{id,type:'New Purchase',vendor:'Newly confirmed supplier',amount:42.95,state:'complete',at:new Date().toISOString(),message:'Authoritative saved record'},old]})});await w.NestPurchasing.reload();assert.equal(history.querySelectorAll('article').length,2);assert.match(history.textContent,/Authoritative saved record/);w.NestAuth.identity.signedIn=false;d.dispatchEvent(new w.Event('nest-auth-change'));assert.equal(history.textContent,'');}finally{dom.window.close();}});
test('status recovery updates recent submissions without a second send',async()=>{const {w,dom}=await adminBrowser();try{const d=w.document;let sends=0;w.fetch=async(url,opts)=>{const b=opts.body?JSON.parse(opts.body):{operation:'view'};if(b.operation==='preview')return {ok:true,json:async()=>({preview:{id,type:'New Purchase',vendor:'Recovered supplier',amount:19.95,recipient:'clerk@example.test',balance:100,estimatedImpact:19.95,linked:[]}})};if(b.operation==='commit'){sends++;throw Error('Timed out');}return {ok:true,json:async()=>({runs:[{id,type:'New Purchase',vendor:'Recovered supplier',amount:19.95,state:'complete',at:new Date().toISOString(),message:'Saved and sent'}]})};};d.querySelector('#purchase-admin-form').dispatchEvent(new w.Event('submit',{bubbles:true,cancelable:true}));await new Promise(r=>setTimeout(r,10));d.querySelector('#purchase-commit').click();await new Promise(r=>setTimeout(r,20));assert.equal(sends,1);assert.match(d.querySelector('#purchase-submission-history').textContent,/Recovered supplier/);assert.match(d.querySelector('#purchase-submission-history').textContent,/Saved and sent/);}finally{dom.window.close();}});
test('confirmed practice email immediately updates its collapsed list even if the workspace refresh fails',async()=>{const {w,dom}=await adminBrowser();try{const d=w.document,type='Practice Purchase — email preview only';d.querySelector('#purchase-type').value=type;w.fetch=async(url,opts)=>{const b=opts.body?JSON.parse(opts.body):{operation:'view'};if(b.operation==='preview')return {ok:true,json:async()=>({preview:{id,type,vendor:'Practice supplier',amount:12.34,recipient:'clerk@example.test',balance:100,estimatedImpact:0,linked:[]}})};if(b.operation==='commit')return {ok:true,json:async()=>({saved:true,state:'practice-complete',message:'Practice sent only to you'})};throw Error('Workspace slow');};d.querySelector('#purchase-admin-form').dispatchEvent(new w.Event('submit',{bubbles:true,cancelable:true}));await new Promise(r=>setTimeout(r,10));d.querySelector('#purchase-commit').click();await new Promise(r=>setTimeout(r,20));assert.match(d.querySelector('#purchase-practice-summary').textContent,/\(1\)/);assert.equal(d.querySelector('#purchase-practice-history').open,false);assert.match(d.querySelector('#purchase-practice-submissions').textContent,/Practice supplier/);assert.doesNotMatch(d.querySelector('#purchase-submission-history').textContent,/Practice supplier/);}finally{dom.window.close();}});
test('leadership budget reference is read-only and redacts receipts, descriptions, ASB records and source file details',()=>{const {ctx}=harness();ctx.purchaseBudget_=()=>({year:'26_27',balance:1500,revision:'verified'});let privateRead;ctx.purchaseFinancialHistoryData_=(r,includePrivate)=>{privateRead=includePrivate;return {purchases:[{day:'2026-11-02',vendor:'Supplier',total:40,description:'PRIVATE',receipt:'PRIVATE URL',email:'PRIVATE EMAIL'}],sourceUrl:'PRIVATE SHEET',asbRequests:[{private:true}]};};assert.equal(ctx.purchaseBudgetReference_(student).status,403);const report=ctx.purchaseBudgetReference_({...student,groups:['all-leadership']});assert.equal(report.status,200);assert.equal(privateRead,false);assert.deepEqual(Object.keys(report.purchases[0]).sort(),['day','total','vendor']);assert.doesNotMatch(JSON.stringify(report),/PRIVATE|asbRequests|sourceUrl/);assert.equal(ctx.purchaseFinancialHistory_({...student,groups:['all-leadership']},{}).status,403);});
test('school bridge permits current leadership chart reads while denying ordinary members and private history',()=>{const source=fs.readFileSync('google-spinner/Purchasing.js','utf8');for(const leader of [false,true]){const ctx=staffContext({email_:s=>s.toLowerCase(),authSession_:()=>({email:'member@example.test',username:'Example'}),PropertiesService:{getScriptProperties:()=>({})}});vm.runInContext(source,ctx);ctx.purchasingActor_=()=>({...student,groups:leader?['all-leadership']:[]});let payload;ctx.purchasingBudgetRequest_=(_token,_actor,operation,fields)=>{payload={operation,fields};return {status:200};};assert.equal(ctx.purchasingWork_({operation:'budget-reference',year:'25_26',receipt:'PRIVATE'}).status,leader?200:403);if(leader)assert.equal(JSON.stringify(payload),JSON.stringify({operation:'budget-reference',fields:{}}));assert.equal(ctx.purchasingWork_({operation:'purchase-history'}).status,403);}});

test('service edits synchronize active requests, invalidate purchase previews, archive removals and deduplicate timeout retries',()=>{
 const {ctx,records}=harness(),ticketId='22222222-2222-4222-8222-222222222222',item={id,title:'Caster',quantity:4,unitCost:5.25,url:'https://supplier.example/caster',notes:'Chair repair',fund:'CTE',division:'1'};
 assert.equal(ctx.purchaseServiceImport_(student,{ticketId,items:[item]}).status,200);
 const before={title:item.title,quantity:item.quantity,unitCost:item.unitCost,url:item.url,notes:item.notes,fund:item.fund},after={...before,title:'Replacement caster',quantity:6},r={operation:'service-change',ticketId,itemId:id,changeId:crypto.randomUUID(),change:'edit',before,after};
 records.PurchaseBoardWeb[0].stage='requisition';assert.equal(ctx.purchaseDispatch_(student,r).status,200);assert.equal(records.PurchaseBoardWeb[0].quantity,6);assert.equal(records.PurchaseBoardWeb[0].revision,2);assert.throws(()=>ctx.purchaseLinked_({links:[{id,revision:1}]}),/changed/);
 assert.equal(ctx.purchaseDispatch_(student,r).status,200);assert.equal(records.PurchaseBoardWeb[0].revision,2);assert.equal(ctx.purchaseDispatch_(student,{...r,after:{...after,quantity:10}}).status,409);
 const remove={...r,changeId:crypto.randomUUID(),change:'remove',before:after,after:null};assert.equal(ctx.purchaseDispatch_(student,remove).status,200);assert.equal(records.PurchaseBoardWeb[0].stage,'archived');assert.ok(records.PurchaseBoardWeb[0].sourceService.removedAt);assert.equal(ctx.purchaseDispatch_(student,remove).status,200);assert.equal(records.PurchaseBoardWeb[0].revision,3);assert.equal(records.PurchaseBoardWeb[0].history.at(-1).action,'Removed from service shopping list');assert.ok(records.PurchaseBoardWeb[0].history.at(-1).before.title===undefined);assert.equal(records.PurchaseRunsWeb.length,0);
});
test('service mutations reject other source tickets, unrelated actors, concurrent inventory edits and recorded purchase states',()=>{
 for(const state of ['complete','asb-requested','processing','review-required','']){const {ctx,records}=harness(),ticketId='22222222-2222-4222-8222-222222222222',item={id,title:'Caster',quantity:4,unitCost:5,url:'',notes:'Repair',fund:'CTE',division:'1'};ctx.purchaseServiceImport_(student,{ticketId,items:[item]});const before={...item},r={ticketId,itemId:id,changeId:crypto.randomUUID(),change:'edit',before,after:{...item,quantity:5}};assert.equal(ctx.purchaseServiceChange_({...student,periods:['2']},r).status,403);assert.equal(ctx.purchaseServiceChange_(student,{...r,ticketId:crypto.randomUUID()}).status,404);records.PurchaseBoardWeb[0].purchaseState=state;if(state)assert.equal(ctx.purchaseServiceChange_(student,r).status,409);else{records.PurchaseBoardWeb[0].quantity=8;assert.equal(ctx.purchaseServiceChange_(student,r).status,409);}}
});
test('browser purchasing API cannot call the trusted service-change operation',async()=>{const res=response();await handler({method:'POST',headers:{cookie:'__Host-nest-auth='+'a'.repeat(64),'content-type':'application/json',origin:'https://gknest.org'},body:{operation:'service-change',itemId:id}},res);assert.equal(res.code,400);});

test('service purchase destinations put requisitions in the owner queue and client purchases outside it; status readback is scoped',()=>{const {ctx,records}=harness(),ticketId='22222222-2222-4222-8222-222222222222',item={id,title:'Caster',quantity:4,unitCost:5,url:'',notes:'Repair',fund:'CTE',division:'1'};ctx.purchaseServiceImport_(student,{ticketId,items:[item]});const r={ticketId,itemId:id,changeId:crypto.randomUUID(),change:'route',before:{...item},after:{purchaseRoute:'requisition'}};assert.equal(ctx.purchaseServiceChange_(student,r).status,200);assert.equal(records.PurchaseBoardWeb[0].stage,'requisition');assert.equal(ctx.purchaseServiceStatuses_(student,{ticketId,itemIds:[id]}).items[0].stage,'requisition');assert.equal(ctx.purchaseServiceStatuses_({...student,periods:['2']},{ticketId,itemIds:[id]}).items.length,0);assert.equal(ctx.purchaseServiceChange_(student,{...r,changeId:crypto.randomUUID(),after:{purchaseRoute:'client'}}).status,200);assert.equal(records.PurchaseBoardWeb[0].stage,'tabled');assert.equal(ctx.purchasePublic_(records.PurchaseBoardWeb[0]).sourceService.route,'client');assert.equal(ctx.purchaseServiceStatuses_(student,{ticketId,itemIds:[id]}).items[0].route,'client');});

test('withdrawing a service list hides its requests from Inventory and invalidates old requisitions without touching fiscal records',()=>{const {ctx,records}=harness(),ticketId='22222222-2222-4222-8222-222222222222',item={id,title:'Caster',quantity:4,unitCost:5,url:'',notes:'Repair',fund:'CTE',division:'1'};ctx.purchaseServiceImport_(student,{ticketId,items:[item]});records.PurchaseBoardWeb[0].stage='requisition';assert.equal(ctx.purchaseServiceVisibility_(student,{ticketId,changeId:crypto.randomUUID(),visible:false,itemIds:[id]}).status,200);assert.equal(ctx.purchaseVisible_(admin,records.PurchaseBoardWeb[0]),false);assert.equal(records.PurchaseBoardWeb[0].stage,'tabled');assert.equal(ctx.purchaseServiceVisibility_(student,{ticketId,changeId:crypto.randomUUID(),visible:true,itemIds:[id]}).status,200);assert.equal(ctx.purchaseVisible_(admin,records.PurchaseBoardWeb[0]),true);assert.equal(records.PurchaseBoardWeb[0].stage,'requisition');assert.equal(records.PurchaseRunsWeb.length,0);});
test('client purchase is tracked and archived without a district purchase; follow-up flags are shared and retries deduplicate',()=>{const {ctx,records}=harness(),ticketId='22222222-2222-4222-8222-222222222222',item={id,title:'Caster',quantity:4,unitCost:5,url:'',notes:'Repair',fund:'CTE',division:'1'};ctx.purchaseServiceImport_(student,{ticketId,items:[item]});const r={ticketId,itemId:id,changeId:crypto.randomUUID(),change:'question',text:'Which size?'};assert.equal(ctx.purchaseServiceClientAction_(student,r).status,200);assert.equal(records.PurchaseBoardWeb[0].sourceService.followUp,true);assert.equal(ctx.purchaseServiceClientAction_(student,{...r,changeId:crypto.randomUUID(),change:'answer',text:'2 inches.'}).status,200);assert.equal(records.PurchaseBoardWeb[0].sourceService.followUp,false);const purchased={...r,changeId:crypto.randomUUID(),change:'purchased',text:''};assert.equal(ctx.purchaseServiceClientAction_(student,purchased).status,200);assert.equal(ctx.purchaseServiceClientAction_(student,purchased).status,200);assert.equal(records.PurchaseBoardWeb[0].purchaseState,'client-complete');assert.equal(records.PurchaseBoardWeb[0].stage,'archived');assert.equal(records.PurchaseRunsWeb.length,0);});
